const j = $json.body || $json;
return {
  json: {
    ...j,
    content_key: 'content_' + Date.now(),
    owner_ref: j.owner_ref || 'system',
    title: j.title || 'New Phase 2 Idea',
    brief: j.brief || 'Autogenerated from N8N',
    state: 'idea'
  }
};

const baseUrl = ($env.SUPABASE_URL || '').trim().replace(new RegExp('/$'), '');
const serviceKey = ($env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
const payload = {
  content_key: $json.content_key,
  owner_ref: $json.owner_ref,
  title: $json.title,
  brief: $json.brief
};
try {
  const res = await this.helpers.httpRequest({
    url: `${baseUrl}/rest/v1/phase2_content_items`,
    method: 'POST',
    headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}`, Prefer: 'return=representation' },
    body: payload,
    json: true
  });
  return { json: { ...$json, content_item: res[0], db_status: 'OK' } };
} catch (e) {
  return { json: { ...$json, db_status: 'ERROR', db_error: e.message } };
}

const baseUrl = ($env.NEXTJS_CONTROL_PLANE_BASE_URL || '').trim().replace(new RegExp('/$'), '');
const brokerSecret = ($env.CONTROL_PLANE_SECRET || '').trim();
if (!brokerSecret || !baseUrl) throw new Error('Missing CONTROL_PLANE_SECRET or NEXTJS_CONTROL_PLANE_BASE_URL');

const title = $json.content_item.title;
const brief = $json.content_item.brief;

const prompt = `
You are an expert Social Media Researcher.
Topic: "${title}"
Brief: "${brief}"

Conduct simulated research based on your training data.
Output a concise 2-paragraph viral research packet in Markdown format.
Include 3 key viral hooks and 2 data points or trends.
`;

try {
  const res = await this.helpers.httpRequest({
    url: `${baseUrl}/api/phase2/ai-broker`,
    method: 'POST',
    headers: { 'Authorization': `Bearer ${brokerSecret}`, 'Content-Type': 'application/json' },
    body: {
      model: 'gpt-4o',
      messages: [
        { role: 'system', content: 'You are an expert Social Media Researcher.' },
        { role: 'user', content: prompt }
      ],
      temperature: 0.7
    },
    json: true
  });

  const research_text = res.choices[0].message.content;
  return { json: { ...$json, research_text, agent_status: 'OK' } };
} catch (e) {
  return { json: { ...$json, agent_status: 'ERROR', agent_error: e.message } };
}

