const baseUrl = ($env.SUPABASE_URL || '').trim().replace(new RegExp('/$'), '');
const serviceKey = ($env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
try {
  await this.helpers.httpRequest({
    url: `${baseUrl}/rest/v1/phase2_content_items?id=eq.${$json.content_item.id}`, method: 'PATCH',
    headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}` },
    body: { state: 'QA_ready' }, json: true
  });
  return { json: { ...$json, db_status: 'OK' } };
} catch (e) { return { json: { ...$json, db_status: 'ERROR', db_error: e.message } }; }

const baseUrl = ($env.NEXTJS_CONTROL_PLANE_BASE_URL || '').trim().replace(new RegExp('/$'), '');
const brokerSecret = ($env.CONTROL_PLANE_SECRET || '').trim();
if (!brokerSecret || !baseUrl) throw new Error('Missing CONTROL_PLANE_SECRET or NEXTJS_CONTROL_PLANE_BASE_URL');

const caption = $json.caption_text;
const research = $json.research_text;

const prompt = `
You are a strict QA Reviewer for Social Media Content.
Review the following caption against the research provided.
Research: ${research}
Caption: ${caption}

Respond strictly in JSON format matching this structure:
{
  "verdict": "pass" | "reject",
  "average_score": number (0 to 10),
  "overclaim_risk": number (0 to 10, where 10 is very risky/exaggerated),
  "missing_asset": boolean,
  "notes": "Brief explanation of your verdict"
}
`;

try {
  const res = await this.helpers.httpRequest({
    url: `${baseUrl}/api/phase2/ai-broker`,
    method: 'POST',
    headers: { 'Authorization': `Bearer ${brokerSecret}`, 'Content-Type': 'application/json' },
    body: {
      model: 'gpt-4o',
      messages: [
        { role: 'system', content: 'You are a QA Gatekeeper.' },
        { role: 'user', content: prompt }
      ],
      temperature: 0.0,
      response_format: { type: 'json_object' }
    },
    json: true
  });

  const qa_result = JSON.parse(res.choices[0].message.content);
  return { json: { ...$json, qa_result, agent_status: 'OK' } };
} catch (e) {
  return { json: { ...$json, agent_status: 'ERROR', agent_error: e.message } };
}

if ($json.agent_status === 'ERROR') throw new Error('QA Agent failed: ' + $json.agent_error);

// If QA rejects, throw error to trigger fail-closed routing
if ($json.qa_result.verdict === 'reject') {
  throw new Error('QA_REJECTED: ' + $json.qa_result.notes);
}
return $json;

const baseUrl = ($env.SUPABASE_URL || '').trim().replace(new RegExp('/$'), '');
const serviceKey = ($env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
const payload = {
  content_item_id: $json.content_item.id,
  reviewer_ref: 'agent_qa_bot',
  verdict: 'pass',
  average_score: $json.qa_result.average_score,
  overclaim_risk: $json.qa_result.overclaim_risk,
  missing_asset: $json.qa_result.missing_asset,
  evidence_ref: 'data:text/plain;base64,' + Buffer.from($json.qa_result.notes).toString('base64')
};
try {
  const res = await this.helpers.httpRequest({
    url: `${baseUrl}/rest/v1/phase2_qa_reviews`, method: 'POST',
    headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}` },
    body: payload, json: true
  });
  return { json: { ...$json, db_status: 'OK' } };
} catch (e) { return { json: { ...$json, db_status: 'ERROR', db_error: e.message } }; }

const baseUrl = ($env.SUPABASE_URL || '').trim().replace(new RegExp('/$'), '');
const serviceKey = ($env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
try {
  await this.helpers.httpRequest({
    url: `${baseUrl}/rest/v1/phase2_content_items?id=eq.${$json.content_item.id}`, method: 'PATCH',
    headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}` },
    body: { state: 'QA_passed' }, json: true
  });
  return { json: { ...$json, db_status: 'OK' } };
} catch (e) { return { json: { ...$json, db_status: 'ERROR', db_error: e.message } }; }

const baseUrl = ($env.NEXTJS_CONTROL_PLANE_BASE_URL || '').trim().replace(new RegExp('/$'), '');
const brokerSecret = ($env.CONTROL_PLANE_SECRET || '').trim();

try {
  const res = await this.helpers.httpRequest({
    url: `${baseUrl}/api/phase2/publish-broker`,
    method: 'POST',
    headers: { 'Authorization': `Bearer ${brokerSecret}`, 'Content-Type': 'application/json' },
    body: {
      title: $json.title,
      research_text: $json.research_text,
      caption_text: $json.caption_text,
      visual_uri: $json.visual_uri
    },
    json: true
  });

  return {
    json: {
      ...$json,
      publish_channel: res.channel,
      publish_url: res.publish_url,
      platform_asset_id: res.platform_asset_id,
      agent_status: 'OK'
    }
  };
} catch (e) {
  return { json: { ...$json, agent_status: 'ERROR', agent_error: e.message } };
}

const baseUrl = ($env.SUPABASE_URL || '').trim().replace(new RegExp('/$'), '');
const serviceKey = ($env.SUPABASE_SERVICE_ROLE_KEY || '').trim();

const payload = {
  content_item_id: $json.content_item.id,
  channel: $json.publish_channel,
  platform_asset_id: $json.platform_asset_id,
  publish_url: $json.publish_url
};

try {
  const res = await this.helpers.httpRequest({
    url: `${baseUrl}/rest/v1/phase2_publish_records`, method: 'POST',
    headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}`, 'Prefer': 'return=representation' },
    body: payload, json: true
  });
  return { json: { ...$json, publish_record: res[0], db_status: 'OK' } };
} catch (e) { return { json: { ...$json, db_status: 'ERROR', db_error: e.message } }; }

const baseUrl = ($env.SUPABASE_URL || '').trim().replace(new RegExp('/$'), '');
const serviceKey = ($env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
try {
  await this.helpers.httpRequest({
    url: `${baseUrl}/rest/v1/phase2_content_items?id=eq.${$json.content_item.id}`, method: 'PATCH',
    headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}` },
    body: { state: 'scheduled', scheduled_at: new Date().toISOString() }, json: true
  });
  await this.helpers.httpRequest({
    url: `${baseUrl}/rest/v1/phase2_content_items?id=eq.${$json.content_item.id}`, method: 'PATCH',
    headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}` },
    body: { state: 'published', published_at: new Date().toISOString() }, json: true
  });
  return { json: { ...$json, db_status: 'OK' } };
} catch (e) { return { json: { ...$json, db_status: 'ERROR', db_error: e.message } }; }

const baseUrl = ($env.WEBHOOK_URL || 'http://localhost:5678').trim().replace(new RegExp('/$'), '');
await this.helpers.httpRequest({
  url: `${baseUrl}/webhook/phase2-error-handler`,
  method: 'POST',
  body: {
    error: $json.error?.message || 'Unknown Error',
    node: $json.execution?.lastNodeExecuted,
    data: $json
  },
  json: true
});
return $json;
